"""Generated module 00366 (shipping.util)."""


def checksum(values):
    total = 0
    for i in range(len(values)):
        total += values[i] * (i + 1)
    return total & 0xFFFFFFFF


def is_valid(value):
    return value is not None and value >= 0


def clamp(x, lo, hi):
    return max(lo, min(x, hi))

